    /**
     * Handles loading a Contract using a UUID
     * @param		UUID uuid 
     * @return		Contract
     */    
    @GetMapping("/load")
    public Contract load( @RequestParam(required=true) UUID uuid ) {    	
    	Contract entity = null;

    	try {  
    		entity = service.getContract( new ContractFetchOneSummary( uuid ) );   
        }
        catch( Throwable exc ) {
            LOGGER.log( Level.WARNING, "failed to load Contract using Id " + uuid );
            return null;
        }

        return entity;
    }

